package com.nova.jobs;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="background_jobs",uniqueConstraints=@UniqueConstraint(columnNames={"order_id","job_type"})) public class BackgroundJob { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="order_id",nullable=false) private Long orderId; @Column(name="job_type",nullable=false) private String jobType; @Column(nullable=false) private String status="PENDING"; @Column(nullable=false,length=1000) private String message="Waiting for processing"; @Column(nullable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); protected BackgroundJob(){} public BackgroundJob(Long orderId,String type){this.orderId=orderId;this.jobType=type;} public Long getId(){return id;}public Long getOrderId(){return orderId;}public String getJobType(){return jobType;}public String getStatus(){return status;}public String getMessage(){return message;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}public void processing(){status="PROCESSING";message="Task is being processed";updatedAt=Instant.now();}public void complete(String text){status="COMPLETED";message=text;updatedAt=Instant.now();}public void fail(String text){status="FAILED";message=text;updatedAt=Instant.now();}}
